from typing import Any
from typing import TextIO
import csv
import io

import pandas as pd

REQUIRED_COLUMNS = ('name', 'email', 'role')
VALID_ROLES = ('admin', 'editor', 'viewer')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


# pcat: importers.users_csv.parse@v1
def import_users(source: str | TextIO, max_rows: int=MAX_ROWS) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    reader = csv.DictReader(io.StringIO(source) if isinstance(source, str) else source)
    header = [h.strip().lstrip('\ufeff').lower() for h in reader.fieldnames or []]
    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        return ([], [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}])
    reader.fieldnames = header
    valid, errors, seen = ([], [], set())
    for count, row in enumerate(reader, 1):
        if count > max_rows:
            stop = f'more than {max_rows} rows; stopped'
            errors.append({'row': reader.line_num, 'errors': [stop]})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        role = (row.get('role') or '').strip().lower()
        age_raw = (row.get('age') or '').strip()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or ('@' in domain) or ('.' not in domain.strip('.')):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        if not role:
            problems.append('role is required')
        elif role not in VALID_ROLES:
            problems.append(f"role must be one of: {', '.join(VALID_ROLES)}")
        if age_raw and (not (age_raw.isdigit() and int(age_raw) <= 150)):
            problems.append('age must be a whole number from 0 to 150')
        if problems:
            errors.append({'row': reader.line_num, 'errors': problems})
        else:
            seen.add(email)
            valid.append({'name': name, 'email': email, 'role': role, 'age': int(age_raw) if age_raw else None})
    return (valid, errors)


def validate_users_upload(data: bytes, filename: str, max_rows: int=MAX_ROWS) -> list[dict[str, Any]]:
    """Validate an uploaded CSV/xlsx of new users and return only the bad rows.

    Each item is {"row": <spreadsheet row number, header = row 1>, "errors": [reasons]}.
    All problems in every row are reported; validation never stops at the first error.
    """
    lower = filename.lower()
    if lower.endswith('.xlsx'):
        try:
            frame = pd.read_excel(io.BytesIO(data), dtype=str, keep_default_na=False, nrows=max_rows + 1)
        except Exception:
            return [{'row': 1, 'errors': ['could not read the xlsx file']}]
        text = frame.to_csv(index=False)
    elif lower.endswith('.csv'):
        try:
            text = data.decode('utf-8-sig')
        except UnicodeDecodeError:
            return [{'row': 1, 'errors': ['file is not valid UTF-8']}]
    else:
        return [{'row': 1, 'errors': ['unsupported file type; upload .csv or .xlsx']}]
    return import_users(text, max_rows)[1]


# ---------------------------------------------------------------- tests (pytest)
def _csv(text: str) -> bytes:
    return text.encode('utf-8')


def test_reports_all_problems_per_row_without_stopping():
    data = _csv(
        'name,email,role\n'
        'Ann,ann@example.com,admin\n'      # row 2: ok
        ',not-an-email,boss\n'             # row 3: three problems
        'Bob,ANN@example.com,viewer\n'     # row 4: duplicate of row 2
        'Cy,cy@example.com,\n'             # row 5: missing role
    )
    errors = validate_users_upload(data, 'users.csv')
    assert [e['row'] for e in errors] == [3, 4, 5]
    assert errors[0]['errors'] == [
        'name is required',
        'email is invalid',
        'role must be one of: admin, editor, viewer',
    ]
    assert errors[1]['errors'] == ['duplicate email']
    assert errors[2]['errors'] == ['role is required']


def test_valid_file_returns_no_errors():
    data = _csv('name,email,role,age\nAnn,ann@example.com,Admin,30\nBob,bob@example.com,viewer,\n')
    assert validate_users_upload(data, 'ok.csv') == []


def test_missing_required_column_and_bad_extension():
    errors = validate_users_upload(_csv('name,email\nAnn,ann@example.com\n'), 'u.csv')
    assert errors == [{'row': 1, 'errors': ['missing columns: role']}]
    assert 'unsupported' in validate_users_upload(b'x', 'u.txt')[0]['errors'][0]


def test_xlsx_upload_matches_csv_behaviour():
    buf = io.BytesIO()
    pd.DataFrame(
        {'name': ['Ann', 'Bob'], 'email': ['ann@example.com', 'bad'], 'role': ['admin', 'viewer']}
    ).to_excel(buf, index=False)
    errors = validate_users_upload(buf.getvalue(), 'users.xlsx')
    assert errors == [{'row': 3, 'errors': ['email is invalid']}]

